ProcessInstanceAsyncWaiter::ProcessInstanceAsyncWaiter(
    ProcessInstance* proxy) : proxy_(proxy) {}

ProcessInstanceAsyncWaiter::~ProcessInstanceAsyncWaiter() = default;

void ProcessInstanceAsyncWaiter::RequestProcessList(
    std::vector<RunningAppProcessInfoPtr>* out_processes) {
  base::RunLoop loop;
  proxy_->RequestProcessList(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<RunningAppProcessInfoPtr>* out_processes
,
             std::vector<RunningAppProcessInfoPtr> processes) {*out_processes = std::move(processes);
            loop->Quit();
          },
          &loop,
          out_processes));
  loop.Run();
}

std::vector<RunningAppProcessInfoPtr> ProcessInstanceAsyncWaiter::RequestProcessList(
    ) {
  std::vector<RunningAppProcessInfoPtr> async_wait_result;
  RequestProcessList(&async_wait_result);
  return async_wait_result;
}

